/* Signature Saraiki Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmedditta": "From Ahmed + Ditta.", "Fatimagul": "From Fatima + gul (flower).", "Muhammadnur": "From Muhammad + nur (light).", "Aminagul": "From Amina + gul.", "Allahdittanur": "From Allah Ditta + nur.", "Ghulamnabi": "From Ghulam + Nabi (prophet): 'servant of the Prophet'.", "Ahmedlangah": "Signature tribal-style surname.", "Fatimakhosa": "Signature tribal-style surname.", "Muhammadleghari": "Signature tribal-style surname.", "Aminamazari": "Signature tribal-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmedditta';
console.log(lookup(q));

